    score: 20,
    outlineAnswer: "1. 定位：散文成就不低，《湘行散记》《湘西》为精品\n2. 写作方式：回程写就与地方事物合成\n3. 特点一：比小说更集中传诉湘西人生方式\n4. 特点二：更直接的历史感受、更多感慨议论\n5. 散文与小说的互文关联\n6. 情感基调：'美丽得使人悲伤'\n7. 历史哲学：变数与常数、两种历史\n8. 批判锋芒与文论散文诗",
    answer: "一、总体定位。教材认为沈从文的散文成就不低，'更重要的散文精品当数《湘行散记》《湘西》两书'。它们是抗战前后两次还乡的产物，'等于是他的自传'，是关于他与故乡、与文学的感情生活的传记性延长；'又如一个山水长卷'，画出包括五条支流、十个县份、百个河码头的沅水流域。《湘行散记》1936年3月由商务印书馆出版，《湘西》1939年8月由长沙商务印书馆出版。\n\n二、写作方式。《湘行散记》循由下游至上游的回乡路程，边回忆、边对照地写下来；《湘西》则按代表性的地方和事物、插入抗战期间对故乡的议论合成。\n\n三、特点一：比小说更集中。两书将湘西的人生方式通过景物印象与人事哀乐一一传诉，'比小说更集中'。写常德的船，实写湘西人情物产风习；辰河小船上的水手曾是土匪却憨厚，把玩妓女的钱买桔子飨客；沅陵的描写穿插神话传说；对凤凰女子放蛊、行巫、落洞的风俗加以现代解释；写被激流带走的水手在一刹那间交代'遗嘱'；老年纤夫长相如同托尔斯泰，'人快到八十了，对于生存还那么努力执著'。\n\n四、特点二：更直接的历史感受。散文比小说有更直接的历史感受，因此有更多的感慨和议论。'时间这个东西十分古怪。一切人一切事都会在时间下被改变'，而重返湘西所见却相反，时间仿佛凝滞——《老伴》中绒线铺女孩十七年前后'还是那么一个样子'。教材概括为关于历史变数与常数的思考：湘西的'常数'、历史循环形态更具典型意义。\n\n五、两种历史与无言的哀戚。散文区分统治阶级的书面历史与人民的无言历史：湘西人'应付生存的方法与排泄感情的娱乐'古今相同（《箱子岩》，注19）；他们'忠实庄严的生活，担负了自己那份命运'，历史对他们俨然毫无意义，然而提到这点千年不变无可记载的历史，'却使人引起无言的哀戚'。\n\n六、散文与小说的互文。作者有意无意将散文描写与小说关联，点出人物在湘西活生生地存在：《鸭窠围的夜》里像'柏子'的水上人；《一九三四年一月十八》里'我'想象如柏子上岸并遇到五年行踪不明的'虎雏'（后写《虎雏再遇记》）；《老伴》交待泸溪绒线铺女孩是《边城》翠翠的原型；《一个多情水手与一个多情妇人》里观音般的妓女竟叫夭夭；《沅陵的人》讲周家菜园四女儿人称夭妹或周家夭夭。\n\n七、情感基调。'人物和地方都美丽得使人悲伤'；'我心中似乎毫无渣滓，透明烛照，对万汇百物，对拉船人与小小船只，一切都那么爱着，十分温暖的爱着！'——写作小说时的感情，在散文里找得到实在的线索。\n\n八、批判锋芒。散文对湘西衰败保守一面的批评'比小说触目得多'：批评'湘西人负气与自弃'（《湘西》题记，注21）；发问'浦市地方屠户也那么瘦小，是谁的责任？'（《辰河小船上的水手》，注22），因湘西屠户历来是胖子，民族败落、人种萎缩到如此程度须要讨论究竟。\n\n九、散文整体功能与文论。散文比小说更能表现'乡下人'自闯入文坛以来走过的个人道路及所遭遇的孤独感；《从文自传》从出生叙到离开湘西近二十年，'只是他艰难历程中的一段心和梦的历史'，比《记丁玲》《记胡也频》更能表现和解剖自己的灵魂。抗战时期文论结集《烛虚》《云南看云集》中，《水云》《绿魔》《潜渊》'简直就是一篇篇散文诗'，谈美学哲学，向'纯'生命的文学思路发展。",
    highScoreAnswer: "沈从文散文成就不低，'更重要的散文精品当数《湘行散记》《湘西》两书'，是抗战前后两次还乡的产物，'等于是他的自传'，'又如一个山水长卷'，画出沅水流域五条支流、十个县份、百个河码头。《湘行散记》循下游至上游的回乡路程边回忆边对照地写，《湘西》按代表性地方事物插入议论合成。其艺术特点：一是将湘西人生方式通过景物印象与人事哀乐传诉，'比小说更集中'；二是比小说有更直接的历史感受、更多感慨议论；三是与小说互文，《老伴》点明绒线铺女孩是翠翠原型，《鸭窠围的夜》水上人似柏子；四是情感上'人物和地方都美丽得使人悲伤'，'一切都那么爱着，十分温暖的爱着'；五是历史哲学上思考时间的变数与常数、区分书面历史与人民的无言历史，'使人引起无言的哀戚'；六是批判锋芒'比小说触目得多'，批评'湘西人负气与自弃'、发出浦市屠户瘦小之问。",
    keywords: ["湘行散记", "湘西", "散文艺术", "还乡", "山水长卷", "沅水流域", "景物印象", "人事哀乐", "历史感受", "变数与常数", "无言的历史", "无言的哀戚", "从文自传", "烛虚", "云南看云集", "散文诗", "负气与自弃"],
    points: ["散文成就不低，《湘行散记》《湘西》为更重要精品", "两次还乡的产物，'等于是他的自传'", "如山水长卷，画出沅水流域全貌", "《湘行散记》边回忆边对照，《湘西》按地方事物合成", "传诉湘西人生方式'比小说更集中'", "比小说有更直接的历史感受、更多感慨议论", "散文描写与小说人物有意无意的关联", "'人物和地方都美丽得使人悲伤'", "时间的变数与常数之思，时间仿佛凝滞", "统治阶级书面历史与人民无言历史之分", "对湘西衰败保守的批评'比小说触目得多'", "《水云》《绿魔》《潜渊》'简直就是一篇篇散文诗'"],
    examples: ["《鸭窠围的夜》水上人似柏子", "《一九三四年一月十八》想象上岸遇虎雏", "《老伴》绒线铺女孩为翠翠原型", "《一个多情水手与一个多情妇人》观音般妓女名夭夭", "《沅陵的人》周家夭夭/夭妹", "写常德的船实写湘西人情物产风习", "辰河水手曾是土匪却买桔子飨客", "凤凰女子放蛊、行巫、落洞风俗的现代解释", "被激流带走的水手刹那交代'遗嘱'", "老年纤夫如托尔斯泰，八十岁仍努力执著", "《箱子岩》古今相同的生存方法与娱乐", "浦市屠户瘦小之问", "'湘西人负气与自弃'（《湘西》题记）"],
